import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/students")
public class StudentController {

    @GetMapping
    public String getAllStudents() {
        return "Student list";
    }

    @GetMapping("/{id}")
    public String getStudent(@PathVariable Long id) {
        return "Student ID: " + id;
    }
}

import jakarta.validation.Valid;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

record StudentRequest(
    @NotBlank String name,
    @NotBlank @Email String email
) {}

@RestController
@RequestMapping("/api/students")
public class StudentCreateController {

    @PostMapping
    public ResponseEntity<StudentRequest> create(
            @Valid @RequestBody StudentRequest request) {
        return ResponseEntity.status(HttpStatus.CREATED).body(request);
    }
}

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Service;

@Entity
class Student {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    private String name;

    protected Student() {}

    public Student(String name) {
        this.name = name;
    }

    public Long getId() { return id; }
    public String getName() { return name; }
}

interface StudentRepository extends JpaRepository<Student, Long> {}

@Service
class StudentService {
    private final StudentRepository repository;

    StudentService(StudentRepository repository) {
        this.repository = repository;
    }

    public Student create(String name) {
        return repository.save(new Student(name));
    }

    public Student findById(Long id) {
        return repository.findById(id)
            .orElseThrow(() -> new IllegalArgumentException("Student not found"));
    }
}

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

record ApiError(String message) {}

class StudentNotFoundException extends RuntimeException {
    StudentNotFoundException(Long id) {
        super("Student not found: " + id);
    }
}

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(StudentNotFoundException.class)
    public ResponseEntity<ApiError> handleNotFound(
            StudentNotFoundException exception) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
            .body(new ApiError(exception.getMessage()));
    }
}
